-- Import Firebird FTBTMBOMSCHRIJVING export into the source catalogue table.
-- CNK is stored as text to preserve leading zeroes; SYNKEY padding is trimmed.
-- Safe to re-run: existing source keys are refreshed from this CSV snapshot.
BEGIN;

CREATE TABLE IF NOT EXISTS public.xt_chem (
    cnk         VARCHAR(7) NOT NULL,
    bron        VARCHAR(1) NOT NULL,
    taalcode    VARCHAR(1) NOT NULL,
    syn         VARCHAR(1) NOT NULL,
    synkey      VARCHAR(4) NOT NULL,
    standaard   CHAR(1) NOT NULL CHECK (standaard IN ('Y', 'N')),
    omschr      TEXT NOT NULL DEFAULT '',
    CONSTRAINT xt_chem_source_key_uq UNIQUE (cnk, bron, taalcode, syn)
);

CREATE INDEX IF NOT EXISTS xt_chem_cnk_idx ON public.xt_chem (cnk);

ON CONFLICT (cnk, bron, taalcode, syn) DO UPDATE SET
    synkey = EXCLUDED.synkey,
    standaard = EXCLUDED.standaard,
    omschr = EXCLUDED.omschr;

